//! Exercises items generated by a macro from another crate.
//!
//! `Counter` and `Counter::incr` are defined in `macrolib/src/lib.rs`, but they
//! are in module `viamacro`, where the macro is invoked, so they go into the
//! `Viamacro` module.

macrolib::define_counter!(Counter);

pub fn make() -> Counter {
    Counter { value: 0 }
}
